// src/api/NotificationsApi.js
import { get, post } from './HttpClient';

/**
 * 알림(Notifications) = AI 결과가 있는 로그(aiLabel 존재)
 * 백엔드에 /alerts가 없으므로 /logs를 재사용한다.
 */

function toQuery(params = {}) {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null) return;
    const s = String(v).trim();
    if (!s) return;
    sp.set(k, s);
  });
  const qs = sp.toString();
  return qs ? `?${qs}` : '';
}

function isAiAlert(log) {
  const v = (log?.aiLabel ?? '').toString().trim();
  return v.length > 0;
}

/**
 * fetchAlerts
 * - /logs 페이지형 호출 후 aiLabel 있는 것만 알림으로 필터링
 * - (level이 있으면 서버에서 aiLabel 필터 가능)
 */
export async function fetchAlerts({
  page = 1,
  size = 20,
  keyword = '',
  level = '', // DANGER | WARNING | SAFE | ''
  from = '',
  to = '',
  sort = 'collectedAt,desc',
} = {}) {
  const res = await get(
    `/logs${toQuery({
      page,
      size,
      keyword,
      aiLabel: level,
      from,
      to,
      sort,
    })}`
  );

  const items = Array.isArray(res?.items) ? res.items : [];
  const aiItems = items.filter(isAiAlert);

  return {
    items: aiItems,
    total: typeof res?.total === 'number' ? res.total : aiItems.length,
    page: res?.page ?? page,
    size: res?.size ?? size,
  };
}

/** 알림 상세 = 로그 상세 */
export function fetchAlertDetail(id) {
  return get(`/logs/${id}`);
}

/**
 * 알림 통계(선택)
 * - /logs/export(JSON)로 가져와서 aiLabel 기준 보고 싶을 때 사용 가능
 */
export async function fetchAlertStats({
  from = '',
  to = '',
  keyword = '',
  level = '', // DANGER/WARNING/SAFE
} = {}) {
  const items = await post('/logs/export', {
    format: 'JSON',
    ids: [],
    filters: {
      from,
      to,
      keyword,
      aiLabel: level,
      eventType: '',
      sort: 'collectedAt,asc',
    },
  });

  const logs = Array.isArray(items) ? items : [];
  const aiLogs = logs.filter(isAiAlert);

  const counter = { total: 0, DANGER: 0, WARNING: 0, SAFE: 0, UNKNOWN: 0 };
  aiLogs.forEach((n) => {
    counter.total += 1;
    const label = (n.aiLabel || 'UNKNOWN').toUpperCase();
    if (counter[label] !== undefined) counter[label] += 1;
    else counter.UNKNOWN += 1;
  });

  return { counter };
}

/** (레거시) 단순 recent 기반 */
export async function fetchNotifications(limit = 100) {
  const res = await get(`/logs/recent?limit=${Number(limit) || 100}`);
  const list = Array.isArray(res) ? res : [];
  return list.filter(isAiAlert);
}
